import { readdir, readFile, writeFile } from "node:fs/promises";
import { resolve, join } from "node:path";
import { pathToFileURL } from "node:url";

export const generatedHeader =
  "# Generated by PicMagic preview-cache-headers; do not edit.";
export function previewCacheHeaders(filenames) {
  const versioned = [...new Set(filenames)]
    .filter((name) => /^[a-z0-9-]+-[a-f0-9]{10}(?:-thumb)?\.webp$/.test(name))
    .sort();
  return `${generatedHeader}\n\n${versioned.map((name) => `/previews/${name}\n  Cache-Control: public, max-age=31536000, immutable\n`).join("\n")}`;
}

/** Build artifact only. Never changes source images, next.config, or remote settings. */
export async function writePreviewHeaders(
  root = process.cwd(),
  dist = process.env.PICMAGIC_DIST_DIR || ".next",
) {
  if (!/^\.next(?:-[a-z0-9-]+)?$/.test(dist))
    throw new Error("Expected a local Next build directory");
  const output = join(root, dist, "_headers");
  const existing = await readFile(output, "utf8").catch((error) => {
    if (error.code !== "ENOENT") throw error;
    return null;
  });
  if (existing !== null && !existing.startsWith(generatedHeader + "\n"))
    throw new Error("Refusing to replace a non-generated _headers file");
  const entries = await readdir(join(root, "public/previews"), {
    withFileTypes: true,
  });
  const content = previewCacheHeaders(
    entries.filter((entry) => entry.isFile()).map((entry) => entry.name),
  );
  await writeFile(output, content, { flag: existing === null ? "wx" : "w" });
  return output;
}

if (
  process.argv[1] &&
  import.meta.url === pathToFileURL(resolve(process.argv[1])).href
) {
  console.log(
    `Prepared versioned-preview cache headers: ${await writePreviewHeaders()}`,
  );
}
